<section class="columns is-centered"><div class="column is-half-tablet is-one-third-widescreen"><div class="box"><h1 class="title is-3">Create your account</h1><p class="mb-4">Verify your email address before signing in.</p><div id="register-message" class="notification is-hidden" role="status" aria-live="polite"></div>
<form id="register-form"><div class="field"><label class="label" for="name">Full name</label><input class="input" id="name" name="name" maxlength="150" autocomplete="name" required></div><div class="field"><label class="label" for="email">Email</label><input class="input" id="email" name="email" type="email" maxlength="254" autocomplete="email" required></div><div class="field"><label class="label" for="username">Username (optional)</label><input class="input" id="username" name="username" maxlength="80" autocomplete="username"></div><div class="field"><label class="label" for="password">Password</label><input class="input" id="password" name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></div><div class="field"><label class="label" for="password_confirmation">Confirm password</label><input class="input" id="password_confirmation" name="password_confirmation" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></div><button class="button is-primary is-fullwidth" type="submit">Create account</button></form><p class="mt-4"><a href="{{ route('login') }}">Back to sign in</a></p></div></div></section>
<script nonce="{{ request()->attributes->get('csp_nonce') }}">
(() => {const form=document.getElementById('register-form'),message=document.getElementById('register-message'),button=form.querySelector('button');form.addEventListener('submit',async event=>{event.preventDefault();button.disabled=true;message.className='notification is-info';message.textContent='Creating your account…';const data=Object.fromEntries(new FormData(form));try{const response=await fetch('/api/v1/auth/register',{method:'POST',headers:{'Accept':'application/json','Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw new Error(result.message||Object.values(result.errors||{}).flat().join(' ')||'Registration could not be completed.');form.hidden=true;message.className='notification is-success';message.textContent='Account created. Check your email for the verification token, then verify your address before signing in.';try{sessionStorage.setItem('verificationEmail',data.email);}catch{}}catch(error){message.className='notification is-danger';message.textContent=error.message||'Unable to contact the server.';}finally{button.disabled=false;}});})();
</script>
